    'trust.example.label': 'ข้อมูลตัวอย่าง',
    'trust.example.madeUpNote': 'ข้อมูลสมมุติ ไม่มีสัตว์ ฟาร์ม เจ้าของ หรือคลินิกใดในไฟล์นี้อยู่จริง',
    'trust.example.rows': '{rows} แถว',
